INSERT INTO books VALUES('72b0130d-e634-43de-8769-05aaf700bab2','Muối Tép Hành','muoi-tep-hanh','NO','No','<h1>🌶️<strong> MUỐI TÔM TÂY NINH NHUYỄN – TÔM TÍ TÁCH </strong>🦐</h1><h2><strong>🏷️ Thông Tin Sản Phẩm</strong></h2><ul><li><strong>📌 Tên sản phẩm:</strong> Muối Tôm Tây Ninh Nhuyễn – Tôm Tí Tách</li><li><strong>⚖️ Khối lượng:</strong> 100g / 200g / 500g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Muối hạt tinh khiết</li><li class="ql-indent-1">Tôm tươi biển 🦐</li><li class="ql-indent-1">Ớt đỏ cay nồng 🌶️</li><li class="ql-indent-1">Tỏi 🧄</li><li class="ql-indent-1">Đường mía 🍯</li><li class="ql-indent-1">Gia vị tự nhiên 🌿</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Chấm trái cây 🍉🍍🥭</li><li>✔️ Dùng với hải sản 🦑🐙</li><li>✔️ Rắc lên bánh tráng, cơm cháy 🍘</li><li>✔️ Nêm nếm món ăn 🥗</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Để nơi khô ráo, thoáng mát 🏡</li><li class="ql-indent-1">Đậy kín sau khi sử dụng 🔒</li></ul><h2><br></h2><h2><strong>✨ Mô Tả Sản Phẩm</strong></h2><h3><strong>🔥 Hương Vị Đậm Đà - Chất Lượng Tinh Tuyền 🔥</strong></h3><p>🌊 <strong>Mỗi hạt muối</strong> là kết tinh của biển cả, mỗi sợi <strong>tôm tươi</strong> là tinh hoa thiên nhiên. Tất cả hòa quyện trong hũ <strong>Muối Tôm Tây Ninh Nhuyễn</strong> của <strong>Tôm Tí Tách</strong>, mang đến <strong>vị ngon không thể trộn lẫn</strong>.</p><p>🦐 <strong>Tôm biển tươi rói</strong> được tuyển chọn kỹ lưỡng, giữ trọn vị <strong>ngọt thanh</strong> và độ <strong>đậm đà tự nhiên</strong>.</p><p>🌶️ <strong>Ớt đỏ Tây Ninh</strong> cay nồng, phơi dưới <strong>nắng gió Tây Ninh</strong>, tạo nên sắc đỏ rực rỡ và hương thơm đặc trưng.</p><p>🧄 <strong>Tỏi thơm nồng</strong>, <strong>muối tinh khiết</strong> được chế biến theo quy trình <strong>sạch và khép kín</strong>, giữ nguyên <strong>sự tinh túy</strong> mà <strong>không cần chất bảo quản</strong>.</p><p>💥 <strong>Hòa quyện giữa:</strong></p><ul><li><strong>Vị mặn dịu</strong> của muối</li><li><strong>Vị ngọt thanh</strong> từ đường mía</li><li><strong>Chút cay tê tê</strong> của ớt</li><li><strong>Hương thơm nồng nàn</strong> từ tỏi</li></ul><p>🔸 <strong>Không phẩm màu - Không phụ gia</strong></p><p>🔸 <strong>Chỉ có nguyên liệu tươi ngon nhất</strong></p><p>🔸 <strong>Chế biến theo phương pháp truyền thống</strong></p><p>🔸 <strong>Đảm bảo vệ sinh &amp; giữ trọn bản sắc</strong></p><p>👉 Đây không chỉ là <strong>muối tôm</strong>, đây là <strong>hương vị Tây Ninh nguyên bản</strong>, mang đến <strong>sự trọn vẹn trong từng hũ nhỏ</strong>! ❤️</p>',55000.0,'https://utfs.io/f/PkAo1zbAWYxQanJtyULlVhiRemoMUWEuvAx3TysgqF2f1P6N',1738998096113,1738998275613,'34d0f8e5-d27c-4ea9-80dc-44d3f9dc74d9',0,0,0,0);
INSERT INTO books VALUES('d02e7020-8744-485b-a996-1c11dff4d3f8','Muối Tôm Nhuyễn','muoi-tom-nhuyen','No','No','<h1>🌶️ MUỐI TÔM NHUYỄN – TÔM TÍ TÁCH 🦐</h1><h2>🏷️ Thông Tin Sản Phẩm</h2><ul><li><strong>📌 Tên sản phẩm:</strong> Muối Tôm Nhuyễn – Tôm Tí Tách</li><li><strong>⚖️ Khối lượng:</strong> 100g / 200g / 500g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Muối hạt tinh khiết 🌊</li><li class="ql-indent-1">Tôm biển tươi 🦐</li><li class="ql-indent-1">Ớt đỏ Tây Ninh 🌶️</li><li class="ql-indent-1">Tỏi 🧄</li><li class="ql-indent-1">Đường mía 🍯</li><li class="ql-indent-1">Gia vị tự nhiên 🌿</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Chấm trái cây 🍉🥭🍏</li><li>✔️ Rắc lên bánh tráng, cơm cháy 🍘</li><li>✔️ Nêm nếm món ăn 🍛</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Đậy kín sau khi sử dụng 🔒</li><li class="ql-indent-1">Bảo quản nơi khô ráo, thoáng mát 🌬️</li></ul><h2><br></h2><h2>✨ Mô Tả Sản Phẩm</h2><h3><strong>🔥 Muối Tôm Hạt Đặc Biệt – Hạt To, Vị Đậm, Ngon Tròn Trịa 🔥</strong></h3><p>🌊 <strong>Không chỉ là muối tôm</strong>, đây là <strong>phiên bản nâng cấp</strong> dành riêng cho những ai <strong>yêu thích vị đậm đà</strong> và hạt muối <strong>giòn rụm</strong>.</p><p>🦐 <strong>Tôm biển tươi</strong> mang lại vị ngọt tự nhiên, kết hợp cùng <strong>muối biển tinh khiết</strong> tạo nên sự hòa quyện hoàn hảo.</p><p>🌶️ <strong>Ớt đỏ Tây Ninh</strong> cay nồng, đúng chuẩn Tây Ninh chính gốc, kích thích vị giác.</p><p>🧄 <strong>Tỏi thơm lừng</strong>, muối rang vừa đủ độ, không quá khô, không quá ẩm, giữ <strong>độ giòn tan</strong> khi chạm vào đầu lưỡi.</p><p>💥 <strong>Trải nghiệm vị giác khó quên:</strong></p><ul><li><strong>Cắn nhẹ một hạt</strong>, vị <strong>cay the nhẹ nhàng</strong> lan tỏa</li><li><strong>Vị béo ngọt</strong> của tôm biển <strong>bùng nổ</strong></li><li><strong>Hương vị mặn ngọt hài hòa</strong>, đánh thức mọi giác quan</li></ul><p>🍋 Dùng để chấm xoài, cóc, ổi? <strong>Hoàn hảo.</strong></p><p>🍘 Rắc lên cơm cháy, bánh tráng? <strong>Tuyệt vời.</strong></p><p>🍲 Nêm nếm món ăn? <strong>Chắc chắn sẽ tạo nên sự khác biệt.</strong></p><p>🔸 <strong>Không phẩm màu - Không phụ gia</strong></p><p>🔸 <strong>Nguyên liệu tươi ngon, chế biến thủ công</strong></p><p>🔸 <strong>Hương vị nguyên bản, tinh túy trong từng hạt muối</strong></p><p>👉 Một hũ nhỏ, một thế giới hương vị Tây Ninh đậm đà! ❤️</p>',35000.0,'https://utfs.io/f/PkAo1zbAWYxQosSmC5waldSw2IV3b4Gk9zxBiE6Jgryu8RHj',1738999681987,1738999681987,'34d0f8e5-d27c-4ea9-80dc-44d3f9dc74d9',0,0,0,0);
INSERT INTO books VALUES('2b2cda10-ae25-491b-a398-ee7ab48176f6','Muối Tôm Hạt Đặc Biệt','muoi-tom-hat-dac-biet','No','No','<h1>🌶️ MUỐI TÔM HẠT ĐẶC BIỆT – TÔM TÍ TÁCH 🦐</h1><h2>🏷️ Thông Tin Sản Phẩm</h2><ul><li><strong>📌 Tên sản phẩm:</strong> Muối Tôm Hạt Đặc Biệt – Tôm Tí Tách</li><li><strong>⚖️ Khối lượng:</strong> 100g / 200g / 500g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Muối biển tinh khiết 🌊</li><li class="ql-indent-1">Tôm tươi 🦐</li><li class="ql-indent-1">Ớt đỏ Tây Ninh 🌶️</li><li class="ql-indent-1">Tỏi 🧄</li><li class="ql-indent-1">Đường mía 🍯</li><li class="ql-indent-1">Gia vị tự nhiên 🌿</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Chấm xoài, cóc, ổi 🍋🥭🍏</li><li>✔️ Rắc lên cơm cháy, bánh tráng 🍘</li><li>✔️ Dùng cho tôm lắc, khoai lắc 🍤🍟</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Giữ kín nắp sau khi dùng 🔒</li><li class="ql-indent-1">Tránh nơi ẩm thấp 🚫💧</li></ul><p><br></p><p><br></p><h2>✨ Mô Tả Sản Phẩm</h2><h3><strong>🔥 Muối Sặc Tôm Tí Tách Đặc Biệt – Đậm Vị Độc Đáo, Ngon Khó Cưỡng 🔥</strong></h3><p><br></p><p>🌊 <strong>Muối Sặc –</strong> một <strong>biến tấu đặc biệt</strong> dành cho những ai thích <strong>vị đậm đà, cay nồng, hậu ngọt</strong>, đúng chuẩn <strong>Tây Ninh chính gốc</strong>.</p><p>🦐 <strong>Tôm biển tươi</strong> giàu dinh dưỡng, kết hợp cùng <strong>muối biển tinh khiết</strong> tạo nên <strong>hương vị tròn trịa, khó quên</strong>.</p><p>🌶️ <strong>Ớt đỏ Tây Ninh</strong> cay nồng <strong>đánh thức vị giác</strong>, tạo nên cảm giác <strong>tê tê đầy kích thích</strong>.</p><p>🧄 <strong>Tỏi thơm nồng</strong>, muối <strong>sấy khô chuẩn nhiệt độ</strong>, giữ được <strong>độ giòn rụm</strong> và <strong>hương thơm đặc trưng</strong>.</p><p>💥 <strong>Trải nghiệm vị giác độc đáo:</strong></p><ul><li><strong>Mặn mà vừa đủ</strong>, không gắt, không lấn át</li><li><strong>Hậu ngọt tự nhiên</strong> từ tôm biển, để lại dư vị khó quên</li><li><strong>Chút cay nồng</strong> kích thích vị giác, càng ăn càng mê</li></ul><p>🍏 Chấm trái cây? <strong>Hết sảy!</strong></p><p>🍘 Rắc lên bánh tráng, cơm cháy? <strong>Tròn vị!</strong></p><p>🍤 Lắc cùng tôm, khoai? <strong>Tăng hương vị bùng nổ!</strong></p><p>🔸 <strong>Không chất bảo quản - Không phẩm màu</strong></p><p>🔸 <strong>Nguyên liệu tuyển chọn, chế biến thủ công</strong></p><p>🔸 <strong>Hương vị Tây Ninh nguyên bản, đậm đà trong từng hạt muối</strong></p><p>👉 <strong>Một hũ muối – một hành trình vị giác đầy hấp dẫn! ❤️</strong></p>',35000.0,'https://utfs.io/f/PkAo1zbAWYxQRSirZ01rxVmK6kTdStfw2uz3A4HZ0FiO1Uye',1739009196579,1739009240945,'34d0f8e5-d27c-4ea9-80dc-44d3f9dc74d9',0,0,0,0);
INSERT INTO books VALUES('a97ffca5-1899-4379-8cc3-60fb8b3bdf0f','Muối Sặc Đặc Biệt','muoi-sac-dac-biet','No','No','<h1>🌶️ <strong>MUỐI SẶC TÔM TÍ TÁCH ĐẶC BIỆT – TÔM TÍ TÁCH</strong> 🦐</h1><h2>🏷️ <strong>Thông Tin Sản Phẩm</strong></h2><ul><li><strong>📌 Tên sản phẩm:</strong> Muối Sặc Tôm Tí Tách Đặc Biệt – Tôm Tí Tách</li><li><strong>⚖️ Khối lượng:</strong> 100g / 200g / 500g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Muối hạt tinh khiết 🧂</li><li class="ql-indent-1">Tôm biển tươi 🦐</li><li class="ql-indent-1">Ớt xiêm cay nồng 🌶️🔥</li><li class="ql-indent-1">Tiêu sọ ⚫</li><li class="ql-indent-1">Tỏi 🧄</li><li class="ql-indent-1">Gia vị tự nhiên 🌿</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Chấm hải sản 🦑🦞</li><li>✔️ Ăn kèm thịt nướng 🍖🔥</li><li>✔️ Rắc lên cơm nóng 🍚</li><li>✔️ Dùng làm muối ướp 🌶️🥩</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Đậy kín sau khi sử dụng 🔒</li><li class="ql-indent-1">Bảo quản nơi khô ráo, tránh ánh nắng trực tiếp ☀️🚫</li></ul><p><br></p><h2>✨<strong> Mô Tả Sản Phẩm</strong></h2><h3><strong>🔥 Muối Sặc Tôm Tí Tách Đặc Biệt – Đậm Vị Độc Đáo, Ngon Khó Cưỡng 🔥</strong></h3><p><br></p><p>🌊 <strong>Muối Sặc –</strong> một <strong>biến tấu đặc biệt</strong> dành cho những ai thích <strong>vị đậm đà, cay nồng, hậu ngọt</strong>, đúng chuẩn <strong>Tây Ninh chính gốc</strong>.</p><p>🦐 <strong>Tôm biển tươi</strong> tuyển chọn kỹ lưỡng, mang lại vị <strong>ngọt thanh tự nhiên</strong>, kết hợp cùng <strong>muối biển tinh khiết</strong> tạo nên <strong>hương vị tròn trịa, khó quên</strong>.</p><p>🌶️ <strong>Ớt xiêm cay nồng</strong> và <strong>tiêu sọ thơm lừng</strong>, giúp <strong>bùng nổ vị giác</strong>, đem đến <strong>cảm giác cay tê đầy kích thích</strong>.</p><p>🧄 <strong>Tỏi thơm nồng</strong>, muối <strong>sấy khô chuẩn nhiệt độ</strong>, giữ được <strong>độ giòn rụm</strong> và <strong>hương thơm đặc trưng</strong>.</p><p>💥 <strong>Trải nghiệm vị giác độc đáo:</strong></p><ul><li><strong>Mằn mặn thanh nhẹ</strong>, không quá gắt</li><li><strong>Hậu ngọt tự nhiên</strong> từ tôm biển, để lại dư vị khó quên</li><li><strong>Chút cay tê từ ớt xiêm và tiêu sọ</strong>, càng ăn càng mê</li></ul><p>🦐 Chấm hải sản? <strong>Đậm đà chuẩn vị!</strong></p><p>🔥 Ăn kèm thịt nướng? <strong>Tăng thêm hương thơm quyến rũ!</strong></p><p>🍚 Rắc lên cơm nóng? <strong>Ngon đến từng hạt cơm!</strong></p><p>🥩 Dùng làm muối ướp? <strong>Thấm đượm hương vị tự nhiên!</strong></p><p>🔸 <strong>Không phẩm màu - Không chất bảo quản</strong></p><p>🔸 <strong>Nguyên liệu tuyển chọn, chế biến thủ công</strong></p><p>🔸 <strong>Hương vị Tây Ninh nguyên bản, đậm đà trong từng hạt muối</strong></p><p>👉 <strong>Một hũ muối – một hành trình vị giác đầy hấp dẫn! ❤️</strong></p>',38000.0,'https://utfs.io/f/PkAo1zbAWYxQGKYbYWQqE8YdaBqV6JoM0tFTnzjRgfcyAI3l',1739009590846,1739009590846,'34d0f8e5-d27c-4ea9-80dc-44d3f9dc74d9',0,0,0,0);
INSERT INTO books VALUES('a80de472-9be3-4740-af64-009fb3ed52b2','Muối Tôm Như Ý','muoi-tom-nhu-y','No','No','<h1>🌶️ <strong>MUỐI TÔM NHƯ Ý – TÔM TÍ TÁCH</strong> 🦐</h1><h2>🏷️ <strong>Thông Tin Sản Phẩm</strong></h2><ul><li><strong>📌 Tên sản phẩm:</strong> Muối Tôm Như Ý – Tôm Tí Tách</li><li><strong>⚖️ Khối lượng:</strong> 100g / 200g / 500g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Muối biển tinh khiết 🌊</li><li class="ql-indent-1">Tôm tươi 🦐</li><li class="ql-indent-1">Ớt đỏ Tây Ninh 🌶️</li><li class="ql-indent-1">Tỏi 🧄</li><li class="ql-indent-1">Đường mía 🍯</li><li class="ql-indent-1">Gia vị tự nhiên 🌿</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Chấm trái cây 🥭🍏🍉</li><li>✔️ Rắc lên gỏi, bánh tráng 🥗🍘</li><li>✔️ Ăn kèm cơm nóng, thịt luộc 🍚🍖</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Giữ kín nắp sau khi sử dụng 🔒</li><li class="ql-indent-1">Tránh nơi ẩm thấp 🚫💧</li></ul><p><br></p><h2>✨ Mô Tả Sản Phẩm</h2><h3><strong>🔥 Muối Tôm Như Ý – Hương Vị Hài Hòa, Cân Bằng Hoàn Hảo 🔥</strong></h3><p><br></p><p>💫 <strong>Nếu bạn đang tìm kiếm một loại muối tôm có vị cay vừa phải, độ mặn dịu nhẹ và vị ngọt hài hòa</strong>, thì <strong>Muối Tôm Như Ý</strong> của <strong>Tôm Tí Tách</strong> chính là lựa chọn lý tưởng.</p><p>🧂 <strong>Muối biển tinh khiết</strong> rang thủ công, giữ được <strong>độ khô vừa phải</strong>, không vón cục, giúp <strong>thấm đều gia vị</strong>.</p><p>🦐 <strong>Tôm biển tươi</strong> được xay nhuyễn, hòa quyện <strong>hoàn hảo</strong> cùng <strong>ớt đỏ cay nhẹ, tỏi thơm nồng và đường mía thanh ngọt</strong>, tạo nên <strong>màu sắc đẹp mắt</strong> và <strong>hương vị cuốn hút</strong>.</p><p>💥 <strong>Trải nghiệm vị giác tuyệt vời:</strong></p><ul><li><strong>Cay nhẹ, không quá nồng</strong> – vừa đủ để kích thích vị giác</li><li><strong>Vị mặn dịu nhẹ</strong> – giúp tôn lên hương vị tự nhiên của món ăn</li><li><strong>Hậu ngọt thanh từ đường mía</strong> – tạo cảm giác tròn vị, dễ ăn</li></ul><p>🥭 Chấm xoài, cóc, ổi? <strong>Tuyệt hảo!</strong></p><p>🍘 Rắc lên bánh tráng, gỏi? <strong>Hấp dẫn khó cưỡng!</strong></p><p>🍚 Ăn kèm cơm nóng, thịt luộc? <strong>Tăng thêm độ ngon trọn vẹn!</strong></p><p>🔸 <strong>Không phẩm màu - Không chất bảo quản</strong></p><p>🔸 <strong>Nguyên liệu tự nhiên, chế biến thủ công</strong></p><p>🔸 <strong>Hương vị Tây Ninh nguyên bản, chuẩn vị từng hạt muối</strong></p><p>👉 <strong>Một hũ nhỏ – một hành trình vị giác tinh tế và hấp dẫn! ❤️</strong></p><p><br></p>',114996.0,'https://utfs.io/f/PkAo1zbAWYxQfzqDjvpiACtJ0dYZLODKcorWnEU9Rmw7VSjb',1739009726949,1739009726949,'34d0f8e5-d27c-4ea9-80dc-44d3f9dc74d9',0,0,0,0);
INSERT INTO books VALUES('4f31ebbb-1392-4dfe-b1ec-4231e720d152','Muối Sốt chấm siêu cay','muoi-sot-cham-sieu-cay','No','No','<h1>🔥 MUỐI SỐT CHẤM SIÊU CAY – TÔM TÍ TÁCH 🌶️🌪️</h1><h2>🏷️ Thông Tin Sản Phẩm</h2><ul><li><strong>📌 Tên sản phẩm:</strong> Muối Sốt Chấm Siêu Cay – Tôm Tí Tách</li><li><strong>⚖️ Khối lượng:</strong> 100g / 200g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Muối biển tinh khiết 🌊</li><li class="ql-indent-1">Ớt xiêm đỏ cay xé lưỡi 🌶️🔥</li><li class="ql-indent-1">Ớt hiểm bùng nổ vị giác 🌪️</li><li class="ql-indent-1">Tỏi thơm nồng 🧄</li><li class="ql-indent-1">Chanh tươi chua dịu 🍋</li><li class="ql-indent-1">Gia vị tự nhiên 🌿</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Chấm hải sản 🦑🦞</li><li>✔️ Thịt nướng, gà luộc 🍗🔥</li><li>✔️ Chấm trái cây, bánh tráng 🥭🍘</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Giữ kín nắp sau khi sử dụng 🔒</li><li class="ql-indent-1">Bảo quản nơi thoáng mát, tránh ánh nắng trực tiếp ☀️🚫</li></ul><p><br></p><h2>✨ Mô Tả Sản Phẩm</h2><h3><strong>🌪️ Muối Sốt Chấm Siêu Cay – Khi Vị Giác Trở Thành Một Cuộc Phiêu Lưu 🔥</strong></h3><p><br></p><p>💥 <strong>Bạn có dám thử một cú chạm đầy táo bạo?</strong> <strong>Muối Sốt Chấm Siêu Cay</strong> không dành cho những ai <strong>ngại thử thách</strong> – đây là <strong>sự bùng nổ vị giác</strong>, một <strong>cơn lốc lửa đỏ</strong> đốt cháy mọi giới hạn!</p><p>🌊 <strong>Muối biển tinh khiết</strong> kết hợp cùng <strong>ớt xiêm đỏ và ớt hiểm</strong> – hai dòng ớt <strong>cay bùng nổ</strong> nhất, tạo nên <strong>sự cay nồng khó cưỡng</strong>.</p><p>🧄 <strong>Tỏi thơm nồng</strong> quyện cùng <strong>chanh tươi chua dịu</strong>, cân bằng vị giác, làm <strong>tăng độ đậm đà</strong> của sốt.</p><p>🔥 <strong>Mỗi giọt sốt là một bản giao hưởng</strong> giữa <strong>vị mặn, chua, cay, ngọt nhẹ</strong>, biến từng món ăn thành <strong>một trải nghiệm bùng nổ</strong>.</p><p>💥 <strong>Trải nghiệm vị giác mãnh liệt:</strong></p><ul><li><strong>Thịt nướng thêm đậm đà</strong>, dậy vị hơn bao giờ hết 🔥🍖</li><li><strong>Hải sản chấm muối sốt, vị tươi ngon trọn vẹn 🦞🌊</strong></li><li><strong>Xoài xanh, cóc, ổi? Chấm một chút là mê ngay! 🥭🍏</strong></li><li><strong>Bánh tráng cuộn? Một cú chấm – cảm giác cay tê len lỏi khắp tế bào!</strong></li></ul><p>🔥 <strong>Không phẩm màu – Không chất bảo quản</strong></p><p>🔥 <strong>Chỉ có ớt thật, muối thật, hương vị thật</strong></p><p>🔥 <strong>Dành riêng cho những tín đồ của vị cay chân chính</strong></p><p>👉 Một hũ <strong>Muối Sốt Chấm Siêu Cay</strong> nhỏ bé nhưng mang <strong>sức mạnh khiến bạn phải xuýt xoa!</strong> <strong>Bạn đã sẵn sàng để chinh phục nó chưa?</strong> 🌪️🌶️🔥</p>',25000.0,'https://utfs.io/f/PkAo1zbAWYxQh1jTw7nCvJZ82r0p9dfSVFGKT4W63s1QaOwe',1739009995746,1739009995746,'7b12811a-0fce-4e50-a37b-65521ec8f27d',0,0,0,0);
INSERT INTO books VALUES('3bfed82c-5907-400d-8146-7004d2e0c9e9','Muối Chấm chéo','muoi-cham-cheo','No','No','<h1>🍃 <strong>MUỐI CHẤM CHÉO – TÔM TÍ TÁCH</strong> 🏔️🔥</h1><h2>🏷️ <strong>Thông Tin Sản Phẩm</strong></h2><ul><li><strong>📌 Tên sản phẩm:</strong> Muối Chấm Chéo – Tôm Tí Tách</li><li><strong>⚖️ Khối lượng:</strong> 100g / 200g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Muối biển tinh khiết 🌊</li><li class="ql-indent-1">Mắc khén cay thơm 🫚</li><li class="ql-indent-1">Tỏi nồng 🧄</li><li class="ql-indent-1">Ớt khô nắng gió 🌶️</li><li class="ql-indent-1">Lá chanh xanh mát 🍃</li><li class="ql-indent-1">Gia vị tự nhiên 🌿</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Chấm thịt nướng, gà luộc 🍗🔥</li><li>✔️ Dùng kèm đồ nướng Tây Bắc 🍖🏔️</li><li>✔️ Chấm lẩu chua cay 🍲🌶️</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Giữ kín nắp sau khi sử dụng 🔒</li><li class="ql-indent-1">Để nơi thoáng mát, tránh ẩm 💨🚫</li></ul><p><br></p><h2>✨ <strong>Mô Tả Sản Phẩm</strong></h2><h3><strong>🏔️ Muối Chấm Chéo – Hương Vị Tây Bắc Đậm Đà, Đầy Mê Hoặc 🔥</strong></h3><p><br></p><p>🌿 <strong>Từ những phiên chợ vùng cao, từ những bếp lửa hồng giữa đại ngàn</strong>, <strong>Muối Chấm Chéo</strong> mang theo <strong>hương vị đặc trưng của núi rừng</strong>, đậm đà mà đầy tinh tế.</p><p>🫚 <strong>Mắc khén cay thơm</strong> – linh hồn của ẩm thực Tây Bắc, tạo nên <strong>vị cay tê độc đáo</strong>.</p><p>🧄 <strong>Tỏi nồng, ớt đỏ khô</strong> – gia vị đậm đà giúp món ăn <strong>thêm chiều sâu hương vị</strong>.</p><p>🍃 <strong>Lá chanh xanh mát</strong> – chút thanh nhẹ, làm dậy lên <strong>sự hài hòa hoàn hảo</strong>.</p><p>🌊 <strong>Muối biển tinh khiết</strong> – cân bằng vị giác, giúp <strong>gia vị hòa quyện một cách tinh tế</strong>.</p><p>💥 <strong>Trải nghiệm vị giác núi rừng:</strong></p><ul><li><strong>Thịt nướng chấm muối chéo</strong> – từng thớ thịt <strong>bừng sáng với hương vị Tây Bắc</strong></li><li><strong>Gà luộc chấm muối chéo</strong> – không chỉ là món ăn, mà còn là <strong>hành trình khám phá vị giác</strong></li><li><strong>Lẩu chua cay chấm thêm muối chéo</strong> – đánh thức <strong>từng tế bào cảm xúc</strong></li></ul><p>🔥 <strong>Không phẩm màu – Không chất bảo quản</strong></p><p>🔥 <strong>Nguyên liệu từ thiên nhiên, chế biến thủ công</strong></p><p>🔥 <strong>Mang đậm hương vị Tây Bắc nguyên bản</strong></p><p>👉 <strong>Một hũ Muối Chấm Chéo – Một vé đến với đại ngàn Tây Bắc! 🏔️🔥</strong></p>',25000.0,'https://utfs.io/f/PkAo1zbAWYxQnJ7U6TvoNuf6BxMp75soZIRagm3Fk09DVLzt',1739010292292,1739010292292,'7b12811a-0fce-4e50-a37b-65521ec8f27d',0,0,0,0);
INSERT INTO books VALUES('06691e5f-7d94-4198-97cc-302552ce60b2','Muối vừng đa hạt','muoi-vung-da-hat','No','No','<h1>🌾 <strong>MUỐI VỪNG ĐA HẠT – HƯƠNG VỊ MỘC MẠC, TINH TẾ 🍂</strong></h1><h2><strong>🏷️ Thông Tin Sản Phẩm</strong></h2><ul><li><strong>⚖️ Khối lượng:</strong> 100g / 200g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Muối biển tinh khiết 🌊</li><li class="ql-indent-1">Vừng trắng, vừng đen rang thơm 🍂</li><li class="ql-indent-1">Lạc rang bùi béo 🥜</li><li class="ql-indent-1">Đậu xanh ngọt nhẹ 🌱</li><li class="ql-indent-1">Tảo biển giàu dinh dưỡng 🌿</li><li class="ql-indent-1">Gia vị tự nhiên 🍃</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Ăn kèm cơm nóng, xôi 🍚🥢</li><li>✔️ Rắc lên bánh tráng, salad 🥗🍘</li><li>✔️ Dùng làm gia vị cho các món chay 🍛🌿</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Đậy kín nắp sau khi sử dụng 🔒</li><li class="ql-indent-1">Bảo quản nơi khô ráo, tránh ánh nắng trực tiếp ☀️🚫</li></ul><p><br></p><h2><strong>✨ Mô Tả Sản Phẩm</strong></h2><h3><strong>🌾 Muối Vừng Đa Hạt – Hương Vị Của Sự Mộc Mạc, Tinh Tế 🍂</strong></h3><p><br></p><p>🍚 <strong>Có những hương vị đơn giản nhưng lại khiến người ta nhớ mãi không quên</strong> – như bát <strong>cơm nóng thơm mùi gạo mới</strong>, như <strong>một nhúm Muối Vừng Đa Hạt rắc lên</strong>, làm bừng sáng cả bữa ăn.</p><p>🥜 <strong>Không chỉ là gia vị</strong>, <strong>Muối Vừng Đa Hạt</strong> là <strong>sự kết tinh của những nguyên liệu thuần túy nhất</strong>:</p><ul><li>🌾 <strong>Vừng trắng, vừng đen</strong> – rang thơm giòn, béo bùi</li><li>🥜 <strong>Lạc rang</strong> – đậm đà, bùi béo đặc trưng</li><li>🌱 <strong>Đậu xanh ngọt nhẹ</strong> – thêm chút thanh tao tự nhiên</li><li>🌿 <strong>Tảo biển</strong> – giàu dinh dưỡng, nâng tầm hương vị</li><li>🌊 <strong>Muối biển tinh khiết</strong> – hài hòa, dịu nhẹ</li></ul><p>💥 <strong>Trải nghiệm hương vị mộc mạc nhưng đầy cuốn hút:</strong></p><ul><li><strong>Rắc lên xôi dẻo</strong> – bữa sáng đơn giản nhưng đầy đủ dinh dưỡng 🍚🥥</li><li><strong>Chấm cùng cơm nóng</strong> – đậm đà, chân thật như những bữa cơm quê ngày bé 🏡</li><li><strong>Cuộn bánh tráng, ăn kèm salad</strong> – vị bùi béo hòa quyện, khó cưỡng 🍘🥗</li></ul><p>🌿 <strong>Không phẩm màu – Không chất bảo quản</strong></p><p>🌿 <strong>Nguyên liệu tự nhiên, rang chín bằng tâm huyết</strong></p><p>🌿 <strong>Muối Vừng Đa Hạt không chỉ là gia vị, mà còn là ký ức, là yêu thương trong từng bữa cơm đầm ấm</strong></p><p>👉 <strong>Một hũ Muối Vừng Đa Hạt – một món quà của sự giản dị mà tinh tế! ❤️</strong></p>',25000.0,'https://utfs.io/f/PkAo1zbAWYxQzqvP3WQG7o9ZWqUNiAemjCy1Qs8XwuRSh2BI',1739010412371,1739010412371,'7b12811a-0fce-4e50-a37b-65521ec8f27d',0,0,0,0);
INSERT INTO books VALUES('3baeddb9-de1f-4217-a8a8-c97151913889','Muối rau răm','muoi-rau-ram','No','No','<h1><strong>🌿 MUỐI RAU RĂM – GIA VỊ NHỎ, HƯƠNG VỊ LỚN 🌶️</strong></h1><h2><strong>🏷️ Thông Tin Sản Phẩm</strong></h2><ul><li><strong>⚖️ Khối lượng:</strong> 100g / 200g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Muối biển tinh khiết 🌊</li><li class="ql-indent-1">Rau răm sấy khô thơm lừng 🌿</li><li class="ql-indent-1">Ớt cay nhẹ 🌶️</li><li class="ql-indent-1">Tỏi nồng 🧄</li><li class="ql-indent-1">Tiêu sọ thơm đặc trưng ⚫</li><li class="ql-indent-1">Gia vị tự nhiên 🍃</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Chấm hột vịt lộn 🥚🌿</li><li>✔️ Chấm xoài, cóc, ổi 🥭🍏</li><li>✔️ Dùng làm gia vị ướp hải sản 🦞🔥</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Đậy kín sau khi sử dụng 🔒</li><li class="ql-indent-1">Bảo quản nơi thoáng mát, tránh ẩm mốc 💨🚫</li></ul><p><br></p><h2><strong>✨ Mô Tả Sản Phẩm</strong></h2><h3><strong>🌿 Muối Rau Răm – Gia Vị Nhỏ, Hương Vị Lớn 🔥</strong></h3><p><br></p><p>🌱 <strong>Tưởng chừng như chỉ là một nhúm rau xanh bình dị</strong>, nhưng <strong>rau răm</strong> lại mang trong mình <strong>hương thơm đặc biệt</strong> khiến bao món ăn bỗng trở nên <strong>hấp dẫn hơn</strong>. Khi kết hợp cùng <strong>muối biển tinh khiết, tỏi nồng, ớt cay nhẹ</strong>, <strong>Muối Rau Răm</strong> ra đời – <strong>một gia vị độc đáo, khó tìm nhưng dễ gây thương nhớ</strong>.</p><p>🌊 <strong>Muối biển tinh khiết</strong> giữ nguyên <strong>vị mặn tự nhiên</strong>, quyện cùng <strong>rau răm sấy khô thơm lừng</strong>, thêm chút <strong>cay tê</strong> của <strong>ớt</strong>, chút <strong>nồng đặc trưng</strong> của <strong>tỏi và tiêu</strong> – tạo nên <strong>một hương vị lạ miệng nhưng đầy cuốn hút</strong>.</p><p>💥 <strong>Trải nghiệm vị giác đầy tinh tế:</strong></p><ul><li>🥚 <strong>Chấm hột vịt lộn</strong> – rau răm và trứng vịt non hòa quyện đến mức <strong>không thể tách rời</strong></li><li>🥭 <strong>Chấm xoài, cóc, ổi</strong> – vị cay nhẹ nhàng kích thích vị giác, <strong>chua, mặn, cay hòa quyện hoàn hảo</strong></li><li>🦞 <strong>Ướp hải sản</strong> – giúp món ăn thêm đậm đà, dậy hương vị tự nhiên</li></ul><p>🔥 <strong>Không phẩm màu – Không chất bảo quản</strong></p><p>🔥 <strong>Nguyên liệu từ thiên nhiên, chế biến thủ công</strong></p><p>🔥 <strong>Đây không chỉ là muối – đây là sự sáng tạo trong ẩm thực, nơi những điều nhỏ bé tạo nên bất ngờ lớn nhất!</strong></p><p>👉 <strong>Bạn đã thử Muối Rau Răm chưa? Nếu chưa, có lẽ bạn vẫn chưa khám phá hết hương vị Việt Nam! ❤️</strong></p>',25000.0,'https://utfs.io/f/PkAo1zbAWYxQKEfAXa5iFwsxd91JoG23tV6rIElgZvnNzMHC',1739010547755,1739010547755,'7b12811a-0fce-4e50-a37b-65521ec8f27d',0,0,0,0);
INSERT INTO books VALUES('6daacc6f-9d69-4810-991f-e9be59c236fd','Muối ô mai xí muội','muoi-o-mai-xi-muoi','No','No','<h1>🍑 MUỐI Ô MAI XÍ MUỘI – CHUA, MẶN, NGỌT, ĐẦY KÝ ỨC TUỔI THƠ 🌿</h1><h2><strong>🏷️ Thông Tin Sản Phẩm</strong></h2><ul><li><strong>⚖️ Khối lượng:</strong> 100g / 200g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Muối biển tinh khiết 🌊</li><li class="ql-indent-1">Ô mai xí muội chua ngọt 🍑</li><li class="ql-indent-1">Mận khô đậm vị 🏺</li><li class="ql-indent-1">Đường phèn thanh nhẹ 🍯</li><li class="ql-indent-1">Cam thảo dịu dàng 🌿</li><li class="ql-indent-1">Gia vị tự nhiên 🍃</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Chấm trái cây chua (xoài, cóc, me) 🥭🍏🌿</li><li>✔️ Pha nước chấm đặc biệt 🥢🥣</li><li>✔️ Trộn cùng bánh tráng 🍘🔥</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Giữ kín nắp sau khi sử dụng 🔒</li><li class="ql-indent-1">Bảo quản nơi khô ráo, tránh ánh sáng mặt trời ☀️🚫</li></ul><p><br></p><p><br></p><h2><strong>✨ Mô Tả Sản Phẩm</strong></h2><h3><strong>🍑 Muối Ô Mai Xí Muội – Chua, Mặn, Ngọt, Đầy Ký Ức Tuổi Thơ ❤️</strong></h3><p><br></p><p>🌸 <strong>Có những hương vị đi qua năm tháng nhưng mãi mãi không thể lãng quên</strong> – như một viên <strong>ô mai xí muội</strong> ngậm đầu lưỡi, <strong>chua chua, mặn mặn, ngọt ngọt</strong>, đánh thức mọi giác quan. <strong>Muối Ô Mai Xí Muội</strong> chính là sự kết tinh của <strong>ký ức ấy</strong>, gói trọn trong từng hạt muối mịn màng, giúp bạn tìm lại <strong>hương vị thân quen của ngày xưa</strong>.</p><p>🍑 <strong>Ô mai xí muội lâu năm</strong> – đậm đà, chua dịu, hậu ngọt tinh tế</p><p>🌊 <strong>Muối biển tinh khiết</strong> – giữ nguyên vị tự nhiên, hài hòa cùng các nguyên liệu khác</p><p>🍯 <strong>Đường phèn thanh mát</strong> – làm dịu vị mặn, cân bằng hương vị hoàn hảo</p><p>🌿 <strong>Cam thảo thơm nhẹ</strong> – tạo độ hậu ngọt dễ chịu, giúp dư vị kéo dài</p><p>💥 <strong>Trải nghiệm vị giác đầy hoài niệm:</strong></p><ul><li><strong>Chấm một miếng cóc non giòn rụm</strong> – vị chua nhẹ, chấm muối xí muội là mê ngay 🍏</li><li><strong>Nhón một miếng xoài xanh chua thanh</strong> – muối tan ngay trong miệng, bùng nổ vị giác 🥭</li><li><strong>Pha nước chấm đặc biệt</strong> – giúp món ăn thêm đậm đà và hấp dẫn hơn 🥣</li><li><strong>Rắc lên bánh tráng, món gỏi</strong> – một biến tấu mới lạ nhưng đầy lôi cuốn 🍘🔥</li></ul><p>🔥 <strong>Không phẩm màu – Không chất bảo quản</strong></p><p>🔥 <strong>Hương vị tự nhiên, tinh khiết nhất</strong></p><p>🔥 <strong>Một hũ muối nhỏ – Một vé trở về tuổi thơ!</strong></p><p>👉 <strong>Nếu bạn yêu thích sự cân bằng hoàn hảo giữa chua, mặn, ngọt – nếu bạn muốn tìm lại những ký ức tuổi thơ trong từng hạt muối nhỏ – Muối Ô Mai Xí Muội chính là lựa chọn dành cho bạn! ❤️</strong></p>',25000.0,'https://utfs.io/f/PkAo1zbAWYxQhrtRfSnCvJZ82r0p9dfSVFGKT4W63s1QaOwe',1739010668760,1739010668760,'7b12811a-0fce-4e50-a37b-65521ec8f27d',0,0,0,0);
INSERT INTO books VALUES('00a8e223-cbcd-4324-a14e-d060839c02a4','Muối tiêu lá chanh','muoi-tieu-la-chanh','No','No','<h1><strong>🍋 MUỐI TIÊU LÁ CHANH – TINH TẾ, THANH TAO, ĐẬM ĐÀ HƯƠNG VIỆT 🌿</strong></h1><h2><strong>🏷️ Thông Tin Sản Phẩm</strong></h2><ul><li><strong>⚖️ Khối lượng:</strong> 100g / 200g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Muối biển tinh khiết 🌊</li><li class="ql-indent-1">Tiêu đen cay thơm ⚫</li><li class="ql-indent-1">Lá chanh sấy thanh mát 🍋</li><li class="ql-indent-1">Tỏi nồng 🧄</li><li class="ql-indent-1">Ớt cay nhẹ 🌶️</li><li class="ql-indent-1">Gia vị tự nhiên 🌿</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Chấm hải sản 🦞🦐</li><li>✔️ Chấm thịt gà luộc 🍗🍋</li><li>✔️ Ăn kèm bít tết 🥩🔥</li><li>✔️ Dùng làm gia vị ướp thịt nướng 🍖</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Đậy kín sau khi sử dụng 🔒</li><li class="ql-indent-1">Để nơi khô ráo, thoáng mát 🌬️🚫</li></ul><p><br></p><h2><strong>✨ Mô Tả Sản Phẩm</strong></h2><h3><strong>🍋 Muối Tiêu Lá Chanh – Tinh Tế, Thanh Tao, Đậm Đà Hương Việt 🌿</strong></h3><p>🌟 <strong>Có những món ăn chỉ khi chấm đúng loại muối mới thực sự tỏa sáng</strong> – và không gì phù hợp hơn một chút <strong>Muối Tiêu Lá Chanh</strong> để <strong>làm dậy lên hương vị</strong> của <strong>gà luộc, hải sản, hay những món ăn thanh đạm</strong>.</p><p>🌊 <strong>Muối biển tinh khiết</strong> được xay nhuyễn, hòa quyện cùng:</p><ul><li>⚫ <strong>Tiêu đen</strong> – cay nồng vừa đủ, làm bừng lên hương vị món ăn</li><li>🍋 <strong>Lá chanh sấy khô</strong> – tạo điểm nhấn thanh mát, dịu nhẹ mà lôi cuốn</li><li>🧄 <strong>Tỏi thơm nồng</strong>, 🌶️ <strong>ớt cay nhẹ</strong> – mang đến hậu vị đậm đà nhưng không quá gắt</li></ul><p>💥 <strong>Trải nghiệm vị giác hoàn hảo:</strong></p><ul><li><strong>Chấm gà ta luộc</strong> – thanh tao nhưng đậm đà, thơm dịu mùi lá chanh 🍗🍋</li><li><strong>Rắc nhẹ lên hải sản</strong> – tôm, cua, sò điệp trở nên tròn vị 🦞🔥</li><li><strong>Pha cùng chanh tươi</strong> – tạo nên loại nước chấm ngon đúng điệu 🍋🥣</li><li><strong>Ướp thịt nướng, bít tết</strong> – gia vị tinh tế giúp món ăn dậy mùi hấp dẫn 🥩🍖</li></ul><p>🔥 <strong>Không phẩm màu – Không phụ gia</strong></p><p>🔥 <strong>Tận dụng hương vị tự nhiên, giữ trọn tinh túy của muối biển và lá chanh</strong></p><p>🔥 <strong>Lựa chọn hoàn hảo cho những ai yêu thích sự thanh nhã trong ẩm thực</strong></p><p>👉 <strong>Nếu bạn đang tìm kiếm một loại muối chấm nhẹ nhàng nhưng không kém phần đặc sắc, hãy để Muối Tiêu Lá Chanh dẫn lối vị giác của bạn! ❤️</strong></p>',25000.0,'https://utfs.io/f/PkAo1zbAWYxQ9EZy8hVhRHmLZ5SxIrkKAMFTNYpXGela3fi0',1739010794706,1739010794706,'7b12811a-0fce-4e50-a37b-65521ec8f27d',0,0,0,0);
INSERT INTO books VALUES('555e2468-5209-4e6a-acea-caeb99169397','Muối ớt xanh','muoi-ot-xanh','No','No','<h1><strong>🌿 MUỐI ỚT XANH – CAY DỊU, THƠM NỒNG, LÔI CUỐN NGAY TỪ MIẾNG ĐẦU TIÊN 🌶️</strong></h1><h2><strong>🏷️ Thông Tin Sản Phẩm</strong></h2><ul><li><strong>⚖️ Khối lượng:</strong> 100g / 200g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Muối biển tinh khiết 🌊</li><li class="ql-indent-1">Ớt xiêm xanh cay nhẹ 🌶️</li><li class="ql-indent-1">Chanh tươi thanh mát 🍋</li><li class="ql-indent-1">Lá chanh non thơm dịu 🍃</li><li class="ql-indent-1">Tiêu đen cay thơm ⚫</li><li class="ql-indent-1">Gia vị tự nhiên 🌿</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Chấm hải sản hấp, nướng 🦞🦐</li><li>✔️ Chấm gà luộc, thịt nướng 🍗🥩</li><li>✔️ Pha nước chấm hải sản đậm vị 🥣🔥</li><li>✔️ Chấm trái cây chua như xoài, cóc, ổi 🥭🍏</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Đậy kín nắp sau khi sử dụng 🔒</li><li class="ql-indent-1">Bảo quản trong tủ lạnh hoặc nơi khô ráo ❄️🌬️</li></ul><p><br></p><p><br></p><h2><strong>✨ Mô Tả Sản Phẩm</strong></h2><h3><strong>🌿 Muối Ớt Xanh – Cay Dịu, Thơm Nồng, Lôi Cuốn Ngay Từ Miếng Đầu Tiên 🌶️</strong></h3><p>🌶️ <strong>Không phải cứ cay xé lưỡi mới khiến người ta say mê</strong> – đôi khi, chỉ cần một chút <strong>cay dịu, thơm nồng</strong> từ <strong>ớt xiêm xanh</strong> cũng đủ làm nên một hương vị <strong>đậm đà khó quên</strong>. <strong>Muối Ớt Xanh</strong> chính là sự hòa quyện hoàn hảo giữa <strong>muối biển tinh khiết, ớt xiêm xanh tươi, lá chanh non</strong> và <strong>chút đường mía thanh nhẹ</strong>, tạo nên <strong>loại muối chấm cay nhẹ nhưng đầy lôi cuốn</strong>.</p><p>🌊 <strong>Muối biển tự nhiên</strong> – giữ trọn vị mặn thanh dịu</p><p>🌶️ <strong>Ớt xiêm xanh tươi</strong> – cay nhẹ, the mát đặc trưng</p><p>🍋 <strong>Chanh tươi và lá chanh</strong> – giúp cân bằng hương vị, tạo độ chua nhẹ dễ chịu</p><p>⚫ <strong>Tiêu đen thơm nồng</strong> – làm nổi bật vị cay, giúp món ăn thêm trọn vị</p><p>💥 <strong>Trải nghiệm vị giác khó cưỡng:</strong></p><ul><li>🦞 <strong>Chấm hải sản hấp, nướng</strong> – vị cay dịu kết hợp với độ ngọt tự nhiên của tôm, cua giúp món ăn <strong>trở nên hoàn hảo</strong></li><li>🥩 <strong>Rắc lên thịt bò nướng</strong> – chỉ cần một chút muối xanh là đủ <strong>làm nổi bật hương vị nguyên bản</strong></li><li>🍏 <strong>Chấm trái cây chua như xoài, cóc, ổi</strong> – tạo nên sự kết hợp <strong>độc đáo giữa cay, chua, mặn, ngọt</strong></li><li>🥣 <strong>Pha thành nước chấm hải sản</strong> – giúp <strong>món ăn thêm bùng nổ hương vị</strong></li></ul><p>🔥 <strong>Không phẩm màu nhân tạo – Không chất bảo quản</strong></p><p>🔥 <strong>Nguyên liệu tươi ngon, chế biến thủ công</strong></p><p>🔥 <strong>Hương vị tự nhiên, cay thanh nhẹ, kích thích vị giác</strong></p><p>👉 <strong>Nếu bạn là tín đồ của vị cay nhưng thích sự nhẹ nhàng, thanh mát, hãy để Muối Ớt Xanh làm phong phú thêm hương vị bữa ăn của bạn! ❤️</strong></p>',25000.0,'https://utfs.io/f/PkAo1zbAWYxQqMIqSxX9d0UKFZnX15DC3ilw7ASR4uHorWay',1739010909257,1739010909257,'7b12811a-0fce-4e50-a37b-65521ec8f27d',0,0,0,0);
INSERT INTO books VALUES('d3b6e717-cc3f-44b1-a3db-7f438b938202','Muối tôm tiêu cay','muoi-tom-tieu-cay','No','No','<h1>🔥 MUỐI TÔM TIÊU CAY – KHI VỊ ĐẬM ĐÀ GẶP GỠ SỰ BÙNG NỔ 🌶️</h1><h2>🏷️ Thông Tin Sản Phẩm</h2><ul><li><strong>⚖️ Khối lượng:</strong> 100g / 200g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Muối biển tinh khiết 🌊</li><li class="ql-indent-1">Tôm khô đậm đà 🦐</li><li class="ql-indent-1">Tiêu đen cay nồng ⚫</li><li class="ql-indent-1">Ớt đỏ phơi nắng 🌶️</li><li class="ql-indent-1">Tỏi thơm nồng 🧄</li><li class="ql-indent-1">Gia vị tự nhiên 🌿</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Chấm trái cây chua (xoài, cóc, ổi) 🥭🍏</li><li>✔️ Rắc lên bánh tráng trộn 🍘🔥</li><li>✔️ Chấm đồ nướng, hải sản 🥩🦞</li><li>✔️ Dùng làm gia vị ướp thịt 🍗🥓</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Giữ kín nắp sau khi sử dụng 🔒</li><li class="ql-indent-1">Bảo quản nơi thoáng mát, tránh ẩm mốc 🌬️🚫</li></ul><p><br></p><h2><br></h2><h2>✨ Mô Tả Sản Phẩm</h2><h3><strong>🔥 Muối Tôm Tiêu Cay – Khi Vị Đậm Đà Gặp Gỡ Sự Bùng Nổ 🌶️</strong></h3><p><br></p><p>🌶️ <strong>Tây Ninh vốn nổi tiếng với muối tôm</strong>, nhưng khi <strong>kết hợp cùng tiêu cay nồng</strong>, <strong>mọi thứ trở nên khác biệt!</strong></p><p>🦐 <strong>Muối Tôm Tiêu Cay</strong> là sự kết hợp <strong>táo bạo và đầy lôi cuốn</strong> giữa:</p><ul><li>🌊 <strong>Muối biển tinh khiết</strong> – vị mặn dịu, giữ trọn hương vị nguyên bản</li><li>🦐 <strong>Tôm khô</strong> – ngọt đậm đà, làm dậy mùi thơm đặc trưng</li><li>⚫ <strong>Tiêu đen cay nồng</strong> – mang đến dư vị tê nhẹ, kích thích vị giác</li><li>🌶️ <strong>Ớt đỏ phơi nắng</strong> – tạo nên màu sắc hấp dẫn và độ cay tê đầu lưỡi</li><li>🧄 <strong>Tỏi thơm lừng</strong> – tăng thêm chiều sâu hương vị</li></ul><p>💥 <strong>Trải nghiệm vị giác bùng nổ:</strong></p><ul><li><strong>Chấm xoài, cóc, ổi</strong> – vị chua của trái cây kết hợp với muối tôm cay cay, không thể cưỡng lại 🥭🍏</li><li><strong>Bánh tráng trộn thêm muối tôm tiêu cay</strong> – hương vị <strong>truyền thống nhưng đậm đà hơn gấp bội</strong> 🍘🔥</li><li><strong>Chấm thịt nướng, hải sản</strong> – <strong>tăng thêm độ ngon, tạo điểm nhấn hương vị</strong> 🥩🦞</li><li><strong>Ướp thịt nướng</strong> – giúp <strong>gia vị thấm đều, mang đến hương vị cay nồng hoàn hảo</strong> 🍗🔥</li></ul><p>🔥 <strong>Không phẩm màu – Không chất bảo quản</strong></p><p>🔥 <strong>Hương vị tự nhiên, cay đậm đà nhưng vẫn giữ sự tinh tế</strong></p><p>🔥 <strong>Một chút muối, một chút tiêu, một chút cay nồng – và rất nhiều sự cuốn hút đang chờ đợi bạn!</strong></p><p>👉 <strong>Bạn đã sẵn sàng để thử thách vị giác của mình với Muối Tôm Tiêu Cay chưa? ❤️</strong></p>',25000.0,'https://utfs.io/f/PkAo1zbAWYxQAStSXRUkKej6qRQEpzB1V95bSfgGl37CusmT',1739010978421,1739010978421,'7b12811a-0fce-4e50-a37b-65521ec8f27d',0,0,0,0);
INSERT INTO books VALUES('00906cb0-556b-4b25-9692-678bbd746e52','Bánh Tráng Muối Tôm Hạt','banh-trang-muoi-tom-hat','No','No','<h1>🔥 BÁNH TRÁNG MUỐI TÔM HẠT – GIÒN RỤM, ĐẬM ĐÀ, GÂY NGHIỆN NGAY TỪ MIẾNG ĐẦU TIÊN 🌶️</h1><h2>🏷️ Thông Tin Sản Phẩm</h2><ul><li><strong>⚖️ Khối lượng:</strong> 200g / 500g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Bánh tráng lúa mì mỏng dai 🍘</li><li class="ql-indent-1">Muối tôm hạt Tây Ninh đậm đà 🦐🧂</li><li class="ql-indent-1">Tỏi phi thơm lừng 🧄</li><li class="ql-indent-1">Hành phi giòn rụm 🧅</li><li class="ql-indent-1">Ớt khô cay nồng 🌶️</li><li class="ql-indent-1">Dầu điều tạo màu hấp dẫn 🏺</li><li class="ql-indent-1">Gia vị tự nhiên 🌿</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Ăn trực tiếp, nhai giòn rụm 🍘🔥</li><li>✔️ Thêm sốt bơ béo ngậy 🥑</li><li>✔️ Kết hợp với trứng cút, xoài bào để tăng hương vị 🥭🥚</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Đậy kín túi sau khi sử dụng 🔒</li><li class="ql-indent-1">Bảo quản nơi khô ráo, tránh ẩm mốc 🌬️🚫</li></ul><p><br></p><p><br></p><h2>✨ Mô Tả Sản Phẩm</h2><h3><strong>🔥 Bánh Tráng Muối Tôm Hạt – Giòn Rụm, Đậm Đà, Gây Nghiện Ngay Từ Miếng Đầu Tiên 🌶️</strong></h3><p>🥢 <strong>Không cần cầu kỳ, chỉ cần một tệp bánh tráng mỏng tang</strong>, hòa cùng chút <strong>muối tôm hạt Tây Ninh cay nồng</strong>, vậy là đủ để <strong>đánh thức mọi giác quan</strong>. <strong>Bánh Tráng Muối Tôm Hạt</strong> không chỉ là một món ăn vặt, mà còn là <strong>một trải nghiệm hương vị khó quên</strong> – nơi từng lớp bánh <strong>dai mềm</strong>, quyện chặt cùng những <strong>hạt muối tôm đậm đà</strong>, tạo nên cảm giác <strong>giòn rụm, dai dai, cay nhẹ nhưng cực kỳ kích thích</strong>.</p><p>🦐 <strong>Muối tôm Tây Ninh</strong> – kết tinh từ <strong>muối biển tinh khiết, tôm khô thơm lừng</strong>, kết hợp cùng <strong>ớt đỏ cay nồng và đường mía thanh nhẹ</strong>.</p><p>🧄 <strong>Tỏi phi, hành phi</strong> – tăng thêm vị bùi béo, thơm nồng không thể cưỡng lại.</p><p>🍘 <strong>Bánh tráng lúa mì</strong> – mềm dẻo, nhai chậm sẽ cảm nhận được <strong>độ giòn nhẹ xen lẫn chút dai đặc trưng</strong>.</p><p>💥 <strong>Trải nghiệm vị giác độc đáo:</strong></p><ul><li><strong>Cay cay, mặn mà nhưng không gắt</strong>, tạo <strong>cảm giác gây nghiện từ miếng đầu tiên</strong></li><li><strong>Từng miếng bánh nhai giòn tan</strong>, hương vị hòa quyện hoàn hảo</li><li><strong>Dễ dàng biến tấu – thêm sốt bơ, trứng cút, xoài bào</strong> để tăng độ ngon gấp bội</li></ul><p>🔥 <strong>Không phẩm màu – Không chất bảo quản</strong></p><p>🔥 <strong>Chỉ có vị ngon chân thật từ những nguyên liệu tự nhiên nhất</strong></p><p>🔥 <strong>Lựa chọn hoàn hảo cho những buổi tụ tập, ăn vặt, hay đơn giản là những lúc thèm một món giòn rụm, đậm vị</strong></p><p>👉 <strong>Nếu bạn yêu thích bánh tráng nhưng muốn cảm nhận từng hạt muối tôm đậm đà một cách chân thực nhất, hãy thử ngay Bánh Tráng Muối Tôm Hạt – giòn, cay, đậm vị, và đầy cuốn hút! ❤️</strong></p>',40000.0,'https://utfs.io/f/PkAo1zbAWYxQE3qJOimraLBpSxeOUZQDRGmP8v2bqjiJ4Ftg',1739011144542,1739011144542,'aa1d0d3a-e413-47f7-b7f0-50f482ddf3a8',0,0,0,0);
INSERT INTO books VALUES('ff266eaf-729a-4037-8cae-26a12c365761','Bánh Tráng Muối Nhuyễn Cay','banh-trang-muoi-nhuyen-cay','No','No','<h1>🔥 BÁNH TRÁNG MUỐI NHUYỄN CAY – CỰC CAY, CỰC ĐẬM, CỰC ĐÃ! 🌶️🔥</h1><h2><strong>🏷️ Thông Tin Sản Phẩm</strong></h2><ul><li><strong>⚖️ Khối lượng:</strong> 200g / 500g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Bánh tráng lúa mì mỏng dai 🍘</li><li class="ql-indent-1">Muối nhuyễn cay bùng nổ 🌶️🔥</li><li class="ql-indent-1">Ớt khô Tây Ninh cay nồng 🌶️</li><li class="ql-indent-1">Dầu hành phi dậy mùi 🧅</li><li class="ql-indent-1">Tỏi phi thơm lừng 🧄</li><li class="ql-indent-1">Gia vị tự nhiên 🌿</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Ăn trực tiếp, nhai giòn rụm 🍘🔥</li><li>✔️ Trộn thêm bò khô, bơ béo ngậy, trứng cút để tăng hương vị 🥑🥚🥩</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Giữ kín túi sau khi sử dụng 🔒</li><li class="ql-indent-1">Bảo quản nơi khô ráo, tránh ẩm mốc 🌬️🚫</li></ul><p><br></p><p><br></p><h2><strong>✨ Mô Tả Sản Phẩm</strong></h2><h3><strong>🔥 Bánh Tráng Muối Nhuyễn Cay – Cực Cay, Cực Đậm, Cực Đã! 🌶️🔥</strong></h3><p><br></p><p>🌶️ <strong>Đã là bánh tráng thì phải cay, phải đậm đà, phải đủ sức đánh thức mọi giác quan ngay từ miếng đầu tiên!</strong> <strong>Bánh Tráng Muối Nhuyễn Cay</strong> chính là món ăn dành riêng cho những <strong>tín đồ thích cảm giác cay bùng nổ</strong>, nơi từng lớp <strong>bánh tráng dai mềm</strong> được phủ đầy <strong>muối nhuyễn cay nồng</strong>, hòa quyện giữa <strong>vị mặn, ngọt, cay đậm đà</strong>, khiến bạn <strong>vừa xuýt xoa vừa không thể dừng lại</strong>.</p><p>🔥 <strong>Khác biệt với bánh tráng muối tôm hạt, phiên bản muối nhuyễn có độ thấm đều hơn</strong>, giúp từng miếng bánh <strong>ngấm gia vị ngay từ lần cắn đầu tiên</strong>.</p><p>🌶️ <strong>Ớt đỏ phơi nắng Tây Ninh</strong> được xay nhuyễn cùng <strong>muối biển tinh khiết</strong>, tạo nên <strong>màu sắc rực rỡ và hương vị cay nồng khó cưỡng</strong>.</p><p>🍘 <strong>Mỗi sợi bánh tráng mềm dai quện chặt với gia vị</strong>, mang đến <strong>trải nghiệm ẩm thực vừa thỏa mãn vị giác, vừa kích thích cơn thèm ăn</strong>.</p><p>💥 <strong>Trải nghiệm vị giác bùng nổ:</strong></p><ul><li><strong>Cay nồng tê đầu lưỡi</strong>, đúng chuẩn dành cho fan "ăn cay không sợ nóng" 🌶️🔥</li><li><strong>Bánh mềm, dai, gia vị thấm đẫm</strong>, càng ăn càng cuốn không thể dừng lại 🍘</li><li><strong>Dễ dàng biến tấu – thêm bò khô, bơ, trứng cút để nhân đôi hương vị! 🥩🥚🥑</strong></li></ul><p>🔥 <strong>Không phẩm màu nhân tạo – Không chất bảo quản</strong></p><p>🔥 <strong>Giữ trọn hương vị nguyên bản của bánh tráng trộn truyền thống</strong></p><p>🔥 <strong>Cay vừa đủ để kích thích, đậm đà vừa đủ để thỏa mãn vị giác</strong></p><p>👉 <strong>Bạn đã sẵn sàng cho thử thách cay nồng chưa? Hãy thử ngay Bánh Tráng Muối Nhuyễn Cay – món ăn vặt không thể thiếu cho những ai mê cay, mê đậm vị! ❤️🔥</strong></p>',35000.0,'https://utfs.io/f/PkAo1zbAWYxQvXZBhjsVU7HA359unNRXMscwxDFZ8vErWejk',1739011273342,1739011273342,'aa1d0d3a-e413-47f7-b7f0-50f482ddf3a8',0,0,0,0);
INSERT INTO books VALUES('69050bac-ec18-4734-a26a-2516576dba51','Bánh Tráng Muối tôm Hành phi','banh-trang-muoi-tom-hanh-phi','No','No','<h1><strong>🔥 BÁNH TRÁNG MUỐI TÔM HÀNH PHI – THƠM NỒNG, GIÒN RỤM, CÀNG ĂN CÀNG GHIỀN! 🌶️</strong></h1><h2><strong>🏷️ Thông Tin Sản Phẩm</strong></h2><ul><li><strong>⚖️ Khối lượng:</strong> 200g / 500g</li><li><strong>🧂 Thành phần:</strong></li><li class="ql-indent-1">Bánh tráng lúa mì mềm dai 🍘</li><li class="ql-indent-1">Muối tôm Tây Ninh đậm đà 🦐🧂</li><li class="ql-indent-1">Hành phi thơm lừng, giòn rụm 🧅</li><li class="ql-indent-1">Tỏi phi béo bùi 🧄</li><li class="ql-indent-1">Ớt bột cay nồng 🌶️</li><li class="ql-indent-1">Dầu điều tạo màu hấp dẫn 🏺</li><li class="ql-indent-1">Gia vị tự nhiên 🌿</li><li><strong>🍽️ Cách sử dụng:</strong></li><li>✔️ Dùng ăn trực tiếp, nhai giòn rụm 🍘🔥</li><li>✔️ Trộn thêm sa tế cay bùng nổ 🌶️🥄</li><li>✔️ Kết hợp với trứng cút, khô bò để tăng hương vị 🥚🥩🔥</li><li><strong>📦 Bảo quản:</strong></li><li class="ql-indent-1">Đậy kín túi sau khi mở 🔒</li><li class="ql-indent-1">Bảo quản nơi thoáng mát, tránh ẩm mốc 🌬️🚫</li></ul><p><br></p><p><br></p><h2><strong>✨ Mô Tả Sản Phẩm</strong></h2><h3><strong>🔥 Bánh Tráng Muối Tôm Hành Phi – Thơm Nồng, Giòn Rụm, Càng Ăn Càng Ghiền! 🌶️</strong></h3><p><br></p><p>😋 <strong>Có những món ăn không chỉ ngon, mà còn có sức hấp dẫn khiến người ta chẳng thể nào cưỡng lại –</strong> <strong>Bánh Tráng Muối Tôm Hành Phi</strong> chính là một trong số đó. Không chỉ là sự kết hợp giữa <strong>bánh tráng dai mềm</strong> và <strong>muối tôm đậm đà</strong>, phiên bản này còn được bổ sung <strong>hành phi thơm lừng, giòn rụm</strong>, mang đến <strong>tầng hương vị đầy mê hoặc</strong>.</p><p>🦐 <strong>Muối tôm Tây Ninh</strong> – đậm đà, cay nhẹ, quyện chặt vào từng sợi bánh tráng</p><p>🧅 <strong>Hành phi, tỏi phi</strong> – <strong>giòn tan, béo bùi</strong>, làm bùng nổ hương vị ngay từ miếng đầu tiên</p><p>🌶️ <strong>Ớt bột cay nồng</strong> – tạo điểm nhấn cho những ai mê cay</p><p>🍘 <strong>Bánh tráng lúa mì</strong> – mềm dai, thấm đẫm gia vị, càng nhai càng mê</p><p>💥 <strong>Trải nghiệm vị giác khó cưỡng:</strong></p><ul><li><strong>Cay cay, mặn mà nhưng vẫn có chút ngọt thanh</strong> từ đường mía</li><li><strong>Giòn nhẹ của hành phi hòa quyện cùng vị đậm đà của muối tôm</strong>, tạo nên <strong>cảm giác tan chảy trên đầu lưỡi</strong></li><li><strong>Dễ dàng biến tấu – thêm sốt bơ, trộn cùng xoài bào sợi, hoặc đơn giản là vắt thêm tí tắc – hương vị lại càng bùng nổ hơn nữa! 🥑🥭🍋</strong></li></ul><p>🔥 <strong>Không phẩm màu nhân tạo – Không chất bảo quản</strong></p><p>🔥 <strong>Sử dụng nguyên liệu chất lượng, giữ trọn hương vị nguyên bản</strong></p><p>🔥 <strong>Món ăn vặt hoàn hảo cho những ngày tụ tập, cơn thèm ăn bất chợt hoặc đơn giản là để thưởng thức vị ngon khó cưỡng!</strong></p><p>👉 <strong>Càng ăn càng ghiền – bạn đã thử chưa? 😍🔥</strong></p>',35000.0,'https://utfs.io/f/PkAo1zbAWYxQlt4FJUhFIVvQBorXT6n9sYzdZERpqSkwUAG7',1739011379312,1739011379312,'aa1d0d3a-e413-47f7-b7f0-50f482ddf3a8',0,0,0,0);
CREATE TABLE IF NOT EXISTS "orders" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" TEXT NOT NULL,
    "bookId" TEXT NOT NULL,
    "fullname" TEXT NOT NULL,
    "address" TEXT NOT NULL,
    "phone" TEXT NOT NULL,
    "district" TEXT NOT NULL,
    "city" TEXT NOT NULL,
    "email" TEXT,
    "status" TEXT NOT NULL DEFAULT 'pending',
    "note" TEXT,
    "total" NUMERIC(10,2) NOT NULL,
    "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP NOT NULL,
    CONSTRAINT "orders_bookId_fkey" FOREIGN KEY ("bookId") REFERENCES "books" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
